import { IsUUID, IsOptional, IsNumber } from 'class-validator';
import { IsEncoded } from '../../../common/validation';

export class CreateAlbumDto {
  /** Generated by the client: the album's key and name are bound to it. */
  @IsUUID('4')
  id: string;

  @IsUUID()
  vaultId: string;

  /** Album name encrypted under the album key. */
  @IsEncoded(1024)
  nameEncrypted: string;

  @IsEncoded(32)
  nameNonce: string;

  /** The album key wrapped under the vault key. */
  @IsEncoded(128)
  keyWrapped: string;

  @IsEncoded(32)
  keyNonce: string;

  @IsOptional()
  @IsNumber()
  sortOrder?: number;
}
